import assert from 'node:assert/strict';
import { shipOrder } from './src/shipping/domain/shipment.ts';
import { OrderStateError } from './src/orders/domain/order.ts';
for (const frozen of [false, true]) {
 for (const status of ['cancelled', 'pending']) {
  const order = {id:'probe', customerId:'alice', status, items:['sku-1']};
  const before = structuredClone(order);
  if (frozen) { Object.freeze(order.items); Object.freeze(order); }
  if (status === 'cancelled') assert.throws(() => shipOrder(order), OrderStateError);
  else { const result = shipOrder(order); assert.equal(result.status, 'shipped'); assert.notEqual(result, order); assert.deepEqual(result, {...before, status:'shipped'}); }
  assert.deepEqual(order, before);
  console.log(`${status}, frozen=${frozen}: PASS (input unchanged)`);
 }
}
